        <?php if (! $cases) : ?>
            <div class="ssf-inspector-empty"><h2>Inga tilldelade ärenden</h2><p>När en handläggare tilldelar dig en inspektion visas den här.</p></div>
        <?php else : ?>
            <div class="ssf-inspector-case-list">
                <?php foreach ($cases as $item) : $state = $item['report']['status'] ?? 'not_started'; ?>
