            <section class="ssf-inspector-panel" data-ssf-inspector-panel="application"><h3>Ansökan</h3><div class="ssf-inspector-read-table"><div><span>Organisation eller rederi</span><strong><?php echo esc_html($data['applicant_organization'] ?? ''); ?></strong></div><div><span>Adress</span><strong><?php echo nl2br(esc_html($data['applicant_address'] ?? '')); ?></strong></div><div><span>Webbplats</span><strong><?php echo esc_html($data['applicant_website'] ?? ''); ?></strong></div><div><span>Ansökningsväg</span><strong><?php echo esc_html($data['application_path'] ?? ''); ?></strong></div></div></section>
